files.content:
:root {
  --bg: #1a1c2c;
  --card: #2b2d42;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --muted: #8d99ae;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  padding: 16px;
  background-image: linear-gradient(45deg, rgba(255,205,117,0.04) 25%, transparent 25%, transparent 75%, rgba(255,205,117,0.04) 75%),
                    linear-gradient(45deg, rgba(255,205,117,0.04) 25%, transparent 25%, transparent 75%, rgba(255,205,117,0.04) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
}
.card {
  width: min(100%, 380px);
  background: var(--card);
  padding: 28px 24px;
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 #000;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-align: center;
  text-shadow: 2px 2px 0 #000;
}
.field { display: flex; flex-direction: column; gap: 6px; }
label { font-size: 0.95rem; color: var(--muted); letter-spacing: 1px; }
input, select, button {
  font: inherit;
  color: var(--text);
  background: #1a1c2c;
  border: 3px solid var(--muted);
  padding: 10px 12px;
  border-radius: 0;
  width: 100%;
}
input:focus, select:focus, button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}
button {
  background: var(--accent);
  color: #1a1c2c;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  cursor: pointer;
  border-color: var(--accent);
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s;
}
button:hover { filter: brightness(1.1); }
button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #000;
}
#result {
  display: block;
  text-align: center;
  font-size: 2rem;
  font-weight: 700;
  padding: 14px 8px;
  background: #1a1c2c;
  border: 3px solid var(--accent);
  color: var(--accent);
  word-break: break-all;
  min-height: 1.2em;
}
@media (max-width: 400px) {
  .card { padding: 20px 16px; box-shadow: 4px 4px 0 #000; }
  h1 { font-size: 1.3rem; }
  body { font-size: 16px; }
}

(function () {
  'use strict';

  var leftInput = document.getElementById('left');
  var rightInput = document.getElementById('right');
  var operationSelect = document.getElementById('operation');
  var calculateButton = document.getElementById('calculate');
  var resultOutput = document.getElementById('result');

  function parseFinite(value) {
    if (value === null || value === undefined) return null;
    var trimmed = String(value).trim();
    if (trimmed === '') return null;
    var num = Number(trimmed);
    return Number.isFinite(num) ? num : null;
  }

  function compute(left, right, operation) {
    switch (operation) {
      case 'add': return left + right;
      case 'subtract': return left - right;
      case 'multiply': return left * right;
      case 'divide':
        if (right === 0) return null;
        return left / right;
      default: return null;
    }
  }

  function handleCalculate() {
    var left = parseFinite(leftInput.value);
    var right = parseFinite(rightInput.value);
    var operation = operationSelect.value;

    if (left === null || right === null) {
      resultOutput.textContent = 'Error';
      return;
    }

    var result = compute(left, right, operation);
    if (result === null || !Number.isFinite(result)) {
      resultOutput.textContent = 'Error';
      return;
    }

    resultOutput.textContent = String(result);
  }

  calculateButton.addEventListener('click', handleCalculate);

  [leftInput, rightInput, operationSelect].forEach(function (control) {
    control.addEventListener('keydown', function (event) {
      if (event.key === 'Enter') {
        event.preventDefault();
        handleCalculate();
      }
    });
  });
})();
